import React, { useState, useEffect } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:5000/api';

const History = () => {
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchHistory();
  }, []);

  const fetchHistory = async () => {
    try {
      setLoading(true);
      const response = await axios.get(`${API_URL}/history`);
      if (response.data.success) {
        setHistory(response.data.history);
      }
    } catch (err) {
      setError('Failed to fetch history');
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'Unknown';
    try {
      const date = new Date(dateString);
      return date.toLocaleString();
    } catch {
      return dateString;
    }
  };

  return (
    <div className="component-container">
      <h2>Processing History</h2>
      
      {error && <div className="error">{error}</div>}
      
      {loading ? (
        <div className="loading">Loading history...</div>
      ) : history.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '40px', color: '#666' }}>
          No processing history found
        </div>
      ) : (
        <div className="history-list">
          {history.map((item, index) => (
            <div key={index} className="history-item">
              <h3>{item.type === 'image' ? '🖼️ Image' : '🎥 Video'}</h3>
              <p><strong>Filename:</strong> {item.filename}</p>
              <p><strong>Color Blindness Type:</strong> {item.colorblind_type}</p>
              <p><strong>Mode:</strong> {item.mode}</p>
              <p><strong>Timestamp:</strong> {formatDate(item.timestamp)}</p>
              {item.output_filename && (
                <p><strong>Output:</strong> {item.output_filename}</p>
              )}
            </div>
          ))}
        </div>
      )}
      
      <div style={{ textAlign: 'center', marginTop: '20px' }}>
        <button className="button" onClick={fetchHistory}>
          Refresh History
        </button>
      </div>
    </div>
  );
};

export default History;
